// Get a roster character's handle, then temporarily unlock their avatar slot to attach a new one
local hdl = CMND_GET_PARTY_HANDLE(_chr);
local wasLocked = CMND_GET_AVATAR_LOCK_FLAG(hdl);
CMND_SET_AVATAR_ENABLE(hdl, true);
CMND_SET_AVATAR_LOCK_FLAG(hdl, false);
CMND_ATTACH_AVATAR(_chr, _avt);
CMND_SET_AVATAR_LOCK_FLAG(hdl, wasLocked);
